              "label": "Direct workspace contribution 1",
              "before": "test('forms, popups, outside hits and a moved map container prevent stale-position replay',async()=>{for(const block of [x=>x.top({closest:()=>({})}),x=>x.top(null),x=>{x.container.contains=()=>false},x=>x.shift(100)]){const x=setup('3d');x.view.stationary=true;x.move();await x.flush();await x.w.enableTurboCoverageLayer();block(x);await x.flush();assert.equal(x.shown(),false);assert.equal(x.picks(),1)}});\n\ntest('a failed refresh finishes its status without replaying hover or polling',async()=>{const x=setup('2d');x.view.stationary=true;x.move();await x.flush();x.w._t=key=>key;x.w.updateTurboPickWarning=()=>{};x.w.loadTurboCoverageLayer=async()=>{throw Error('offline')};await x.w.enableTurboCoverageLayer();await x.flush();assert.equal(x.shown(),false);assert.equal(x.picks(),1);assert.equal(x.pending(),0)});\ntest('the real click prelude cancels a pending readiness replay',async()=>{const x=setup('2d');x.view.stationary=true;x.move();await x.flush();await x.w.enableTurboCoverageLayer();let click;function find(node){if(ts.isCallExpression(node)&&node.expression.getText(sf)==='view.on'&&node.arguments[0]?.text==='click')click=node.arguments[1];ts.forEachChild(node,find)}find(widget);assert(click);const prelude=click.body.statements.slice(0,2).map(n=>n.getText(sf)).join('\\n'),invoke=new Function(compile('return async()=>{'+prelude+'}')).call(x.w);await invoke();await x.flush();assert.equal(x.picks(),1);assert.equal(x.shown(),false)});\n",
